 selected=next(r for r in rows if r['sigma']==1.5 and r['level']==80);cal.append({'id':m['id'],'sha256':m['contentSha256'],'ratio':selected['ratio'],'lower':min(r['lower'] for r in rows),'upper':max(r['upper'] for r in rows),'class': 'GOOD' if m['sourceMeaning']['fields'].get('quality')=='OK' else 'SKEW','candidates':rows})
